-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create table public.dispute_evidence (
  id uuid default gen_random_uuid() not null,
  order_id uuid not null,
  uploader_id uuid,
  url text not null,
  note text,
  created_at timestamp with time zone default now() not null,
  storage_path text
);

alter table public.dispute_evidence enable row level security;

-- Constraints
alter table public.dispute_evidence add constraint dispute_evidence_note_bounds CHECK (note IS NULL OR char_length(note) <= 500);
alter table public.dispute_evidence add constraint dispute_evidence_order_id_fkey FOREIGN KEY (order_id) REFERENCES public.orders(id) ON DELETE CASCADE;
alter table public.dispute_evidence add constraint dispute_evidence_pkey PRIMARY KEY (id);
alter table public.dispute_evidence add constraint dispute_evidence_uploader_id_fkey FOREIGN KEY (uploader_id) REFERENCES public.profiles(id) ON DELETE SET NULL;

-- Indexes
CREATE INDEX dispute_evidence_order_idx ON public.dispute_evidence USING btree (order_id);
CREATE INDEX dispute_evidence_storage_path_idx ON public.dispute_evidence USING btree (storage_path);
CREATE INDEX dispute_evidence_uploader_id_idx ON public.dispute_evidence USING btree (uploader_id) WHERE (uploader_id IS NOT NULL);

-- Grants
grant all on table public.dispute_evidence to anon;
grant all on table public.dispute_evidence to authenticated;
grant all on table public.dispute_evidence to service_role;
